'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process'),{parse}=require('../audits/audit-i18n-global.cjs');
const root=path.resolve(__dirname,'../..'),assets=process.env.EXIT_FEEDBACK_ASSET_DIR||root,read=f=>fs.readFileSync(path.join(assets,f),'utf8'),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
const proof=JSON.parse(fs.readFileSync(path.join(root,'outils/audits/I18N-EXIT-FEEDBACK-20261116-preuve.json'))),snapshot=(sha,f)=>execFileSync('git',['show',sha+':'+f],{cwd:root,encoding:'utf8',maxBuffer:5e6}),before=f=>snapshot(proof.baseCommit,f);
function fn(source,name){const n=parse(source).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name===name);assert.ok(n,name);return source.slice(n.start,n.end);}
const annotation='  globalThis.RPI18nPlateau?.markToast?.(globalThis.RPNavigationI18n?.exitMessageKey?.(message) || null, message, undefined, titre);\n';
const cases=[
 {id:'session',v:{ok:false,transport:{etat:'session_perdue'}},key:'exitSessionBody'},
 ...['non_authentifie','acteur_non_authentifie','session_perdue'].map(raison=>({id:raison,v:{ok:false,raison},key:'exitSessionBody'})),
 {id:'uncertain',v:{ok:false,transport:{etat:'reseau'}},uncertain:true,key:'exitUnconfirmedBody'},
 {id:'session-priority',v:{ok:false,raison:'non_authentifie'},uncertain:true,key:'exitSessionBody'},
 {id:'network',v:{ok:false,transport:{etat:'reseau'}},key:'exitNetworkBody'},
 {id:'403',v:{ok:false,transport:{etat:'http',http:403,code:'HTTP_403'}},key:'exitForbiddenBody'},
 {id:'500',v:{ok:false,transport:{etat:'http',http:500,code:'secret <token>'}},key:'exitServiceBody'},
 {id:'unregistered',v:{ok:false,raison:'sortie_non_referencee'},key:'exitUnregisteredBody'},
 {id:'invalid',v:{ok:false,transport:{etat:'reponse_invalide'}},key:'exitUnreadableBody'},
 {id:'null',v:null,key:'exitUnreadableBody'},{id:'missing-ok',v:{},key:'exitUnreadableBody'},
 {id:'nonboolean-ok',v:{ok:'false'},key:'exitUnreadableBody'},
 ...['inventaire_surcharge','combat_en_cours','combat_membre_pnj'].map(raison=>({id:raison,v:{ok:false,raison},key:'exitDeniedBody'})),
];
function catalog(source){const c={RP_I18N_RESOURCES:Object.fromEntries(langs.map(l=>[l,{translation:{}}]))};c.window=c;vm.createContext(c);vm.runInContext(source,c);return JSON.parse(JSON.stringify(c.RP_I18N_RESOURCES));}
test('14 textes / 112 traductions : français intégral, neuf langues, anciennes ressources et deux titres réutilisés',()=>{
 const old=catalog(before('i18n/navigation-resources.js')),own=catalog(snapshot(proof.codeCommit,'i18n/navigation-resources.js')),current=catalog(read('i18n/navigation-resources.js'));
 const keys=proof.texts.map(r=>r.key);assert.equal(keys.length,14);
 const c={};vm.createContext(c);vm.runInContext(fn(before('plateau-navigation.js'),'sortieBatimentMessage'),c);
 for(const l of langs){const a=own[l].translation.navigation,b=old[l].translation.navigation;assert.deepEqual(Object.keys(a).filter(k=>!(k in b)).sort(),keys.slice().sort());for(const row of proof.texts){const value=current[l].translation.navigation[row.key];assert.equal(typeof value,'string');assert.ok(value.trim());if(l==='fr')assert.equal(value,row.fr);else assert.notEqual(value,row.fr);assert.equal(value.includes('{{'),false);delete a[row.key];}assert.deepEqual(a,b,l);}
 for(const x of cases){const [title,body]=c.sortieBatimentMessage(x.v,x.uncertain);assert.equal(current.fr.translation.navigation[x.key],body);assert.ok(proof.texts.some(r=>r.fr===title)||['Session expirée','Connexion indisponible'].includes(title));}
 for(const title of ['Session expirée','Connexion indisponible'])assert.equal(proof.texts.some(r=>r.fr===title),false);
});
test('seule annotation du rendu : navigation, gardes, RPC, diagnostics, reconnexion et combats inchangés',()=>{
 const own=snapshot(proof.codeCommit,'plateau-navigation.js');assert.equal(own.split(annotation).length,2);assert.equal(own.replace(annotation,''),before('plateau-navigation.js'));
 for(const f of ['data.js','supabase.js','plateau-core.js','i18n/plateau-init.js','style.css'])assert.equal(snapshot(proof.codeCommit,f),before(f),f);
 function replay(source,x){const calls=[],c={showToast:(...a)=>calls.push(['toast',...a]),reprendreCombatConfirme:()=>{calls.push(['combat']);return Promise.resolve();},afficherBandeauReconnexion:()=>calls.push(['reconnect']),noterIncidentSession:(...a)=>calls.push(['incident',...a])};vm.createContext(c);vm.runInContext(fn(source,'sortieBatimentMessage')+'\n'+fn(source,'signalerEchecSortie'),c);c.signalerEchecSortie('lecture',x.v,x.uncertain);return calls;}
 for(const x of cases)assert.deepEqual(replay(own,x),replay(before('plateau-navigation.js'),x),x.id);
 const names=execFileSync('git',['diff','--name-only',proof.baseCommit,proof.codeCommit],{cwd:root,encoding:'utf8'}).trim().split('\n');assert.deepEqual(names.filter(f=>!['plateau-navigation.js','plateau.html','i18n/navigation-resources.js','i18n/packed/navigation-resources.js.br','outils/audits/I18N-CATALOGUES-TRANSPORT.json','RELAIS.md'].includes(f)),[]);
});
test('Chromium : sorties refusées réelles, neuf langues, 320/390/1280, RTL, état et saisies intacts sans nouvel appel métier',async()=>{
 const {chromium}=require('playwright'),browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:800}}),errors=[],network=[];page.on('pageerror',e=>errors.push(String(e)));await page.route('**/*',r=>{network.push(r.request().url());return r.abort();});
 const html=read('plateau.html'),match=html.match(/<div id="result-toast"[^>]*>[\s\S]*?<div class="toast-sub" id="toast-sub"><\/div>\s*<\/div>/);assert.ok(match);
 await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><input id="draft" value="Brouillon conservé"><div id="scroll" style="height:70px;overflow:auto"><div style="height:200px">Position conservée</div></div>'+match[0]+'</body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});
 await page.evaluate(()=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.trace=[];window.state={char:{name:'Fixture',country:'soviet'},pa:3,arg:700,inventory:[{id:'fixture'}],progression:{stage:2},currentCity:'ville_a',currentBuilding:'universite',currentRoom:'bibliotheque'};window.noterIncidentSession=(...a)=>trace.push(['incident',...a]);window.afficherBandeauReconnexion=()=>trace.push(['reconnect']);window.reprendreCombatConfirme=()=>{trace.push(['combat']);return Promise.resolve();};for(const name of ['fetch','sbRpc','sbRpcVerdict','deduireCoutOrdre','doOrder'])window[name]=(...a)=>{trace.push([name,...a]);throw Error('Appel métier interdit');};window.stable=()=>JSON.stringify({state,trace,timer:window._toastTimer,draft:document.getElementById('draft').value,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:document.getElementById('scroll').scrollTop});});
 for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/toast-resources.js','i18n/toast-bodies-resources.js','i18n/forum-feedback-resources.js','i18n/navigation-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});
 await page.addScriptTag({content:fn(read('plateau-core.js'),'showToast')+'\n'+fn(read('plateau-navigation.js'),'sortieBatimentMessage')+'\n'+fn(read('plateau-navigation.js'),'signalerEchecSortie')+'\n'+fn(before('plateau-navigation.js'),'signalerEchecSortie').replace('function signalerEchecSortie(','function signalerEchecSortieOriginal(')});
 await page.evaluate(()=>{document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,7);document.getElementById('scroll').scrollTop=30;});
 for(const x of cases){const baseline=await page.evaluate(async x=>{await i18next.changeLanguage('en');trace.length=0;signalerEchecSortieOriginal('lecture',x.v,x.uncertain);return {body:document.getElementById('toast-sub').textContent,calls:JSON.stringify(trace),pair:sortieBatimentMessage(x.v,x.uncertain)};},x);assert.equal(baseline.body,baseline.pair[1],x.id+' français résiduel avant raccordement');
 const start=await page.evaluate(async x=>{await i18next.changeLanguage('fr');trace.length=0;signalerEchecSortie('lecture',x.v,x.uncertain);return {snapshot:stable(),calls:JSON.stringify(trace)};},x);assert.equal(start.calls,baseline.calls,x.id+' mêmes conséquences que main');
 for(const lang of langs){const got=await page.evaluate(async({lang,x,title})=>{await i18next.changeLanguage(lang);const sub=document.querySelector('#toast-sub [data-i18n]'),head=document.querySelector('#toast-result [data-i18n]'),toast=document.getElementById('result-toast'),rect=toast.getBoundingClientRect();return {snapshot:stable(),text:sub?.textContent,key:sub?.dataset.i18n,expected:i18next.t('navigation.'+x.key),title:head?.textContent,expectedTitle:RPToastI18n.label(title),dir:sub?.dir,titleDir:head?.dir,overflow:document.documentElement.scrollWidth>innerWidth,inside:rect.left>=0&&rect.right<=innerWidth,bodyInside:sub?.parentElement.scrollWidth<=sub?.parentElement.clientWidth+1,titleInside:head?.parentElement.scrollWidth<=head?.parentElement.clientWidth+1,images:toast.querySelectorAll('img').length};},{lang,x,title:baseline.pair[0]});assert.equal(got.snapshot,start.snapshot,x.id+'/'+lang);assert.equal(got.key,'navigation.'+x.key);assert.equal(got.text,got.expected);if(lang==='fr')assert.equal(got.text,baseline.pair[1]);else assert.notEqual(got.text,baseline.pair[1]);assert.equal(got.title,got.expectedTitle);assert.equal(got.dir,lang==='ar'?'rtl':'');assert.equal(got.titleDir,lang==='ar'?'rtl':'');for(const k of ['overflow'])assert.equal(got[k],false,x.id+'/'+lang+'/'+width+'/'+k);for(const k of ['inside','bodyInside','titleInside'])assert.equal(got[k],true,x.id+'/'+lang+'/'+width+'/'+k);assert.equal(got.images,0);switches++;}
 }
 const fallback=await page.evaluate(async()=>{await i18next.changeLanguage('fr');signalerEchecSortie('lecture',{ok:false});const d=i18next.getResourceBundle('de','translation');delete d.navigation.exitDeniedBody;i18next.removeResourceBundle('de','translation');i18next.addResourceBundle('de','translation',d);await i18next.changeLanguage('de');return document.getElementById('toast-sub').textContent;});assert.equal(fallback,'Le serveur n’autorise pas cette sortie dans votre situation actuelle.');
 await page.evaluate(()=>showToast('Texte libre','Réponse <à conserver> — 123',false));for(const l of ['ar','en','fr']){await page.evaluate(l=>i18next.changeLanguage(l),l);assert.equal(await page.locator('#toast-sub').textContent(),'Réponse <à conserver> — 123');assert.equal(await page.locator('#toast-sub [data-i18n]').count(),0);}
 assert.deepEqual(errors,[]);assert.deepEqual(network,[]);await page.close();}}finally{await browser.close();}assert.equal(switches,cases.length*9*3);console.log(switches+' bascules sans nouvel ordre, RPC, reconnexion, combat ou dépense.');
});
